(()=>{var w=(j)=>document.getElementById(j);async function B(){let j=Number(new URLSearchParams(location.search).get("tab"));if(j)return chrome.tabs.get(j);let[y]=await chrome.tabs.query({active:!0,currentWindow:!0});return y}async function C(){let j=await B(),{enabled:y=!0}=await chrome.storage.local.get("enabled");if(w("enabled").checked=y!==!1,!j?.id)return;let q=await chrome.tabs.sendMessage(j.id,{type:"stats"}).catch(()=>{return});if(!q){w("summary").textContent="The sentry can't read this page (browser pages and the Web Store are off limits).";return}w("summary").textContent=`${q.flagged.length} of ${q.scanned} blocks look like instructions to an AI assistant.`,w("list").replaceChildren(...q.flagged.map((z)=>{let A=document.createElement("li");return A.innerHTML=`<b>${Math.round(z.risk*100)}%</b> <span class="where"></span> <span class="text"></span>`,A.querySelector(".where").textContent=z.where,A.querySelector(".text").textContent=z.text.slice(0,140),A})),w("ask").onclick=async()=>{w("jev").textContent="Asking Jev…";let z=await chrome.runtime.sendMessage({type:"askJev",url:j.url,blocks:q.flagged});w("jev").textContent=z?.error??`Jev's hijack risk: ${z.risks.map((A)=>`${Math.round(A*100)}%`).join(", ")}`}}w("enabled").onchange=async(j)=>{let y=j.target.checked,q=await B();if(await chrome.storage.local.set({enabled:y}),q?.id)await chrome.tabs.sendMessage(q.id,{type:"toggle",enabled:y}).catch(()=>{return})};C();})();
